    """
    Returns integers x and y that satisfy ax + by = n as a tuple, or returns None if no solution exists.

    Args:
        a: coefficient of x
        b: coefficient of y  
        n: constant term

    Returns:
        A tuple (x, y) that satisfies ax + by = n, or None if no solution exists
    """
    # Handle the case where both a and b are 0
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)

    # Handle the case where one of them is 0
    if a == 0:
        return None if n % b != 0 else (0, n // b)

    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    # Use extended Euclidean algorithm to find gcd and coefficients
    def extended_gcd(x, y):
        if x == 0:
            return y, 0, 1
        gcd, a1, b1 = extended_gcd(y % x, x)
        a = b1 - (y // x) * a1
        b = a1
        return gcd, a, b

    gcd, x0, y0 = extended_gcd(a, b)

    # Check if solution exists
    if n % gcd != 0:
        return None

    # Scale the solution to match the right-hand side
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)

    return (x, y)
