    """
    Put spaces between words starting with capital letters in a given string.

    Args:
        s (str): Input string

    Returns:
        str: String with spaces inserted between words that start with capital letters
    """
    if not s:
        return s

    result = []
    i = 0
    while i < len(s):
        if s[i].isupper() and i > 0 and not result or result[-1] == ' ':
            # If current character is uppercase and we're not at start or previous char is space
            # We need to add a space before this uppercase letter
            if i > 0 and result and result[-1] != ' ':
                result.append(' ')
            result.append(s[i])
        else:
            result.append(s[i])
        i += 1

    # Handle the case where we have consecutive uppercase letters
    # We only want to add space between words, not within words
    result = []
    i = 0
    while i < len(s):
        if i == 0 or s[i].islower() or (s[i].isupper() and (i == 0 or s[i-1].islower())):
            result.append(s[i])
        else:
            # Only add space if we're not at the beginning and the previous char is lowercase
            # and current char is uppercase
            if i > 0 and s[i-1].islower() and s[i].isupper():
                result.append(' ')
                result.append(s[i])
            else:
                result.append(s[i])
        i += 1

